import type { HTMLAttributes, ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// A key: DM Sans 12px in the soft neutral, in a 20px #1A1A1A box with a #666666 hairline and the small corner. Key
// names as words or symbols (⌘, Shift, K), never in capitals or mono. Put a shortcut's keys in KbdGroup.
export interface KbdProps extends HTMLAttributes<HTMLElement> {
  children?: ReactNode
}

export const kbdClasses = 'inline-flex h-5 min-w-5 shrink-0 items-center justify-center gap-1 rounded-ds-sm border border-edge-strong bg-surface-subtle px-1 type-caption whitespace-nowrap text-fg-soft select-none'

export function Kbd({ className, children, ...rest }: KbdProps) {
  return <kbd data-ds="kbd" className={cn(kbdClasses, className)} {...rest}>{children}</kbd>
}

export default Kbd

import type { HTMLAttributes, ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// The keys of one shortcut, 4px apart: <KbdGroup><Kbd>⌘</Kbd><Kbd>K</Kbd></KbdGroup>.
export interface KbdGroupProps extends HTMLAttributes<HTMLElement> {
  children?: ReactNode
}

export function KbdGroup({ className, children, ...rest }: KbdGroupProps) {
  return <kbd data-ds="kbd-group" className={cn('inline-flex items-center gap-1', className)} {...rest}>{children}</kbd>
}

export default KbdGroup

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

